BEGIN;
SET LOCAL sf_lifecycle.command='on';
SET LOCAL sf_migration.restoring='on';
SET LOCAL statement_timeout='15s';
DO $$
DECLARE c uuid:=gen_random_uuid(); b jsonb; rid uuid; aid uuid:=gen_random_uuid(); installed uuid:=gen_random_uuid(); sold uuid:=gen_random_uuid(); retired uuid:=gen_random_uuid(); unreserved uuid:=gen_random_uuid(); typ text; day date:=(now() AT TIME ZONE 'America/Los_Angeles')::date; p jsonb; cmd uuid:=gen_random_uuid(); out1 jsonb; n integer; rejected boolean;
BEGIN
 SELECT id INTO typ FROM sauna_types LIMIT 1;
 INSERT INTO customer_profiles(id,display_name) VALUES(c,'Synthetic shipping test');
 b:=rental_lifecycle_command(gen_random_uuid(),'manual_reservation',jsonb_build_object('customerId',c,'sourceKey','synthetic-shipment-'||c));
 rid:=(b->>'rentalId')::uuid;
 UPDATE reservations SET booking_state='confirmed',booking_install_on=day+20,booking_confirmation_mode='manual' WHERE id=(b->>'reservationId')::uuid;
 INSERT INTO sauna_inventory(id,unit_code,sauna_type_id,status,future_customer_id,condition_state,available_date,locations,style,model_key) VALUES(aid,'TEST-SHIP',typ,'Reservation Hold',(b->>'reservationId')::uuid,'ready',day+11,ARRAY['indoor'],'infrared','standard');
 UPDATE reservations SET sauna_inventory_id=aid WHERE id=(b->>'reservationId')::uuid;
 p:=jsonb_build_object('assetId',aid,'status','Incoming','date',day,'incomingEta',day+10,'availableOn',day+11,'reason','Synthetic shipping correction');
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('incomingEta',NULL));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Inbound date is required%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Missing inbound date accepted';END IF;
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('availableOn',day+10));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Booking availability must be after%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Same-day bookable date accepted';END IF;
 out1:=rental_lifecycle_command(cmd,'asset_status',p);
 IF (booking_readiness((b->>'reservationId')::uuid)->>'date')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Valid distinct dates not ready';END IF;
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('availableOn',day+21));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Availability conflicts with a confirmed booking%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Availability ignored when arrival precedes promise';END IF;
 SELECT count(*) INTO n FROM rental_history_events WHERE asset_id=aid;
 IF rental_lifecycle_command(cmd,'asset_status',p)<>out1 OR (SELECT count(*) FROM rental_history_events WHERE asset_id=aid)<>n THEN RAISE EXCEPTION 'Idempotency failed';END IF;
 IF NOT EXISTS(SELECT 1 FROM sauna_inventory WHERE id=aid AND status='Incoming' AND incoming_eta=day+10 AND future_customer_id=(b->>'reservationId')::uuid AND condition_state='ready' AND available_date=day+11) OR NOT EXISTS(SELECT 1 FROM reservations WHERE id=(b->>'reservationId')::uuid AND booking_state='confirmed' AND booking_install_on=day+20) THEN RAISE EXCEPTION 'Reserved shipping changed another fact';END IF;
 UPDATE sauna_inventory SET status='Reservation Hold' WHERE id=aid;
 IF (SELECT status FROM sauna_inventory WHERE id=aid)<>'Incoming' THEN RAISE EXCEPTION 'Reallocation label erased shipping';END IF;
 UPDATE reservations SET booking_state='requested' WHERE id=(b->>'reservationId')::uuid;
 UPDATE sauna_inventory SET future_customer_id=NULL,status='Available' WHERE id=aid;
 IF (SELECT status FROM sauna_inventory WHERE id=aid)<>'Incoming' THEN RAISE EXCEPTION 'Releasing a reservation falsely received the shipment';END IF;
 UPDATE sauna_inventory SET future_customer_id=(b->>'reservationId')::uuid,status='Reservation Hold' WHERE id=aid;
 UPDATE reservations SET booking_state='confirmed',booking_install_on=day+20 WHERE id=(b->>'reservationId')::uuid;
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('incomingEta',day+30,'availableOn',day+31));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Availability conflicts with a confirmed booking%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected OR (SELECT incoming_eta FROM sauna_inventory WHERE id=aid)<>day+10 THEN RAISE EXCEPTION 'Unacknowledged conflict was not rejected atomically';END IF;
 out1:=rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('incomingEta',day+30,'availableOn',day+31,'acknowledgeScheduleConflict',true));
 IF (SELECT incoming_eta FROM sauna_inventory WHERE id=aid)<>day+30 OR jsonb_array_length(out1->'schedulingConflicts')<>1 OR (SELECT future_customer_id FROM sauna_inventory WHERE id=aid)<>(b->>'reservationId')::uuid OR NOT EXISTS(SELECT 1 FROM reservations WHERE id=(b->>'reservationId')::uuid AND booking_state='confirmed' AND booking_install_on=day+20) THEN RAISE EXCEPTION 'Acknowledged shipment correction changed booking facts';END IF;
 IF (booking_readiness((b->>'reservationId')::uuid)->>'date')::boolean THEN RAISE EXCEPTION 'Impossible promise still ready for confirmation';END IF;
 rejected:=false;
 BEGIN PERFORM booking_command_before_completion(gen_random_uuid(),'confirm',jsonb_build_object('id',b->>'reservationId','version',(SELECT booking_version FROM reservations WHERE id=(b->>'reservationId')::uuid),'assetId',aid,'installOn',day+20,'reason','Must not reconfirm before arrival'));EXCEPTION WHEN OTHERS THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Impossible booking could be reconfirmed';END IF;
 PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p);
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('date',day+1));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Status effective date%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Future actual status date accepted';END IF;
 rejected:=false;
 BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('status','Retired'));EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Resolve customer assignments first%' THEN RAISE;END IF;rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Reserved retirement accepted';END IF;
 PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('status','Available'));
 IF NOT EXISTS(SELECT 1 FROM sauna_inventory WHERE id=aid AND status='Reservation Hold' AND future_customer_id=(b->>'reservationId')::uuid AND condition_state='ready') THEN RAISE EXCEPTION 'Receipt lost reservation';END IF;
 UPDATE rentals SET purpose='purchase' WHERE id=rid;
 UPDATE sauna_inventory SET status='Pre-sold' WHERE id=aid;
 PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p);
 PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p||jsonb_build_object('status','Available'));
 IF NOT EXISTS(SELECT 1 FROM sauna_inventory WHERE id=aid AND status='Pre-sold' AND future_customer_id=(b->>'reservationId')::uuid) THEN RAISE EXCEPTION 'Purchase reservation lost on receipt';END IF;
 INSERT INTO sauna_inventory(id,unit_code,sauna_type_id,status,condition_state,locations,style,model_key) VALUES(unreserved,'TEST-UNRESERVED',typ,'Maintenance','inspection',ARRAY['indoor'],'infrared','standard');
 PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',jsonb_build_object('assetId',unreserved,'status','Incoming','date',day,'incomingEta',day+10,'availableOn',day+11,'reason','Known distinct arrival and availability'));
 IF NOT EXISTS(SELECT 1 FROM sauna_inventory WHERE id=unreserved AND status='Incoming' AND incoming_eta=day+10 AND available_date=day+11 AND condition_state='inspection' AND future_customer_id IS NULL) THEN RAISE EXCEPTION 'Unreserved shipping invented condition or ETA';END IF;
 INSERT INTO sauna_inventory(id,unit_code,sauna_type_id,status,current_customer_id,locations,style,model_key) VALUES(installed,'TEST-INSTALLED',typ,'Installed',(b->>'reservationId')::uuid,ARRAY['indoor'],'infrared','standard');
 INSERT INTO sauna_inventory(id,unit_code,sauna_type_id,status,locations,style,model_key) VALUES(sold,'TEST-SOLD',typ,'Sold',ARRAY['indoor'],'infrared','standard');
 INSERT INTO sauna_inventory(id,unit_code,sauna_type_id,status,retired_on,locations,style,model_key) VALUES(retired,'TEST-RETIRED',typ,'Maintenance',day,ARRAY['indoor'],'infrared','standard');
 FOR p IN SELECT jsonb_build_object('assetId',id,'status','Incoming','date',day,'reason','Must reject') FROM sauna_inventory WHERE id IN(installed,sold,retired) LOOP
  rejected:=false;
  BEGIN PERFORM rental_lifecycle_command(gen_random_uuid(),'asset_status',p);EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Record the current rental return first%' THEN RAISE;END IF;rejected:=true;END;
  IF NOT rejected THEN RAISE EXCEPTION 'Protected unit accepted';END IF;
 END LOOP;
 IF has_function_privilege('anon','public.rental_lifecycle_command(uuid,text,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.rental_lifecycle_command(uuid,text,jsonb)','EXECUTE') OR has_function_privilege('service_role','public.rental_lifecycle_before_incoming_fleet(uuid,text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Function permissions expanded';END IF;
END $$;
ROLLBACK;
